<script type="module">
    let lastActiveTabBtn = null;
    let currentActiveChar = null;
    let isInjectionEnabled = false;

    // --- 页面渲染缓存标记 ---
    let tabRendered = { 'page-user': false, 'page-story': false, 'page-opt': false };
    let renderDebounceTimer = null;

    function getInjSuffix() {
        return isInjectionEnabled 
            ? "\n\n(提示词注入开关【已开】：修改将直接通知AI。如需静默修改请在右上角关闭开关)" 
            : "\n\n(当前为静默调整，不会通知AI。⚠️ 注意：如果是重置角色条目、重大改动，请务必先打开右上角开关，否则AI可能会无视修改！)";
    }

    function parseOptions(text) {
        try {
            if (!text) return [];
            const match = text.match(/(?:<options>|<selection>)([\s\S]*?)(?:<\/options>|<\/selection>)/i);
            if (!match || !match[1] || !match[1].trim()) return [];
            const lines = match[1].trim().split(/\r?\n/);
            return lines.filter(l => l && (l.includes('<font') || l.includes('color='))).map(line => {
                try {
                    const tmp = document.createElement('div'); tmp.innerHTML = line;
                    const clean = (tmp.textContent || '').replace(/[\u{1F600}-\u{1F64F}]/gu, '').trim();
                    return { html: line, text: clean };
                } catch (e) { return null; }
            }).filter(item => item !== null);
        } catch (err) { return []; }
    }

    function cleanInputText(text) {
        if (!text) return '';
        const emojiRegex = /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F700}-\u{1F77F}\u{1F780}-\u{1F7FF}\u{1F800}-\u{1F8FF}\u{1F900}-\u{1F9FF}\u{1FA00}-\u{1FA6F}\u{1FA70}-\u{1FAFF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{2300}-\u{23FF}]/gu;
        return text.replace(/\s+/g, '').replace(emojiRegex, '');
    }

    function getData() {
        try { if (typeof getAllVariables === 'function') return getAllVariables().stat_data || {}; } catch(e) {}
        return {};
    }

    function tryApplyStoryLogic(stat_data) {
        let fn = null;
        try { if (typeof calculateStoryLogic === 'function') fn = calculateStoryLogic; } catch(e){}
        if (!fn) try { if (typeof window !== 'undefined' && window.calculateStoryLogic) fn = window.calculateStoryLogic; } catch(e){}
        if (!fn) try { if (typeof globalThis !== 'undefined' && globalThis.calculateStoryLogic) fn = globalThis.calculateStoryLogic; } catch(e){}
        if (!fn) try { if (typeof top !== 'undefined' && top.calculateStoryLogic) fn = top.calculateStoryLogic; } catch(e){}
        if (!fn) try { if (typeof parent !== 'undefined' && parent.calculateStoryLogic) fn = parent.calculateStoryLogic; } catch(e){}

        if (typeof fn === 'function') {
            try { return fn(stat_data); } 
            catch (e) { console.warn("[StatusBar] Story Logic Sync Failed:", e); return stat_data; }
        }
        return stat_data;
    }

    window.toggleInjection = function(e) {
        if(e) e.stopPropagation();
        isInjectionEnabled = !isInjectionEnabled;
        const btn = $('#inj-toggle-btn');
        if (isInjectionEnabled) btn.addClass('active');
        else btn.removeClass('active');
        if (typeof toastr !== 'undefined') toastr.info(isInjectionEnabled ? "已开启变量修改提示词注入" : "已关闭变量修改提示词注入，当前为静默模式");
    };

    window.injectChangePrompt = function(msg) {
        if (!isInjectionEnabled) return;
        let inp = window.parent?.document?.querySelector('#send_textarea') || document.querySelector('#send_textarea');
        if (inp) {
            const promptText = `\n[系统最高优先级指令（状态变量强制变更）：${msg}]`;
            const cur = inp.value.trim();
            inp.value = cur ? `${cur}${promptText}` : promptText.trim();
            inp.dispatchEvent(new Event('input', { bubbles: true }));
            inp.focus();
        }
    };

    // ==========================================
    // 变量修改相关方法（传递最新 mvuData 进行即时渲染）
    // ==========================================
    window.manageItem = async function(name) {
        const d = getData(); const bag = d.主角信息?.物品栏 || {}; const item = bag[name]; if (!item) return;
        const act = prompt(`【${name}】\n📦 类型: ${item.类型 || '杂物'}\n🔢 数量: ${item.数量}\n📝 描述: ${item.描述 || '无描述'}\n\n请输入数字进行操作：\n1. 修改数量/描述\n2. 删除此物品${getInjSuffix()}`, "");
        if (act === '1') {
            const newCount = prompt(`修改【${name}】的数量:`, item.数量); if (newCount === null) return;
            const newDesc = prompt(`修改【${name}】的描述:`, item.描述); if (newDesc === null) return;
            try {
                let mvuData = await Mvu.getMvuData({ type: 'message', message_id: -1 });
                mvuData.stat_data.主角信息.物品栏[name].数量 = Number(newCount);
                mvuData.stat_data.主角信息.物品栏[name].描述 = newDesc;
                mvuData.stat_data = tryApplyStoryLogic(mvuData.stat_data);
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: -1 });
                injectChangePrompt(`玩家手动修改了物品栏中【${name}】的信息。当前数量为：${newCount}，描述更新为：“${newDesc}”。`);
                render(mvuData.stat_data);
            } catch(e) { console.error(e); }
        } else if (act === '2') {
            if (!confirm(`确定要彻底删除物品【${name}】吗？此操作不可恢复！`)) return;
            try {
                let mvuData = await Mvu.getMvuData({ type: 'message', message_id: -1 });
                delete mvuData.stat_data.主角信息.物品栏[name];
