        const trigs = mvuData?.stat_data?.剧情触发器; if (!trigs || !trigs[index]) return; const oldT = trigs[index];
        const newType = prompt(`修改类别:${getInjSuffix()}`, oldT.事件类别); if (newType === null) return;
        const newDesc = prompt("修改简述:", oldT.事件简述); if (newDesc === null) return;
        const newState = prompt("修改状态:", oldT.状态); if (newState === null) return;
        const newTimer = prompt("修改计时:", oldT.事件计时); if (newTimer === null) return;
        trigs[index] = { 事件类别: newType, 事件简述: newDesc, 状态: newState, 事件计时: newTimer };
        mvuData.stat_data = tryApplyStoryLogic(mvuData.stat_data); await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: -1 });
        render(mvuData.stat_data);
    }
