    // 按需渲染角色选项卡
    function renderCharsTab(sd) {
        const chars = sd.女性角色 || {}; 
        const cKeys = Object.keys(chars).sort((a,b) => {
            const aHere = String(chars[a]?.是否在场) === 'true';
            const bHere = String(chars[b]?.是否在场) === 'true';
            if (aHere === bHere) return 0;
            return aHere ? -1 : 1;
        });

        $('#page-chars').html(`<div id="char-nav" class="char-scroll-nav"></div><div id="char-detail"></div>`);
        const nav = $('#char-nav');
        const detail = $('#char-detail');

        if (cKeys.length === 0) {
            detail.html('<div style="text-align:center;padding:20px;color:#666;font-size:12px">暂无角色</div>');
            currentActiveChar = null;
            return;
        }

        if (!currentActiveChar || !cKeys.includes(currentActiveChar)) currentActiveChar = cKeys[0];

        cKeys.forEach((key) => {
            const c = chars[key];
            const isActive = (key === currentActiveChar);
            const isHere = String(c.是否在场) === 'true';
            const opacityStyle = isHere ? '' : 'opacity:0.5;';

            const btn = $(`<div class="char-pill ${isActive?'active':''}" style="${opacityStyle}">${key}<span class="heart-icon">❤${c.好感度||0}</span></div>`);

            // 点击时重新渲染当前选中的角色
            btn.on('click', function() { 
                $('.char-pill').removeClass('active'); $(this).addClass('active'); 
                currentActiveChar = key;

                detail.html('<div style="text-align:center;padding:30px;color:var(--accent-color);font-weight:bold;animation: pulse 1s infinite;">读取档案中...</div>');

                setTimeout(() => {
                    const freshSd = getData();
                    renderCharDetail(key, freshSd.女性角色?.[key]); 
                }, 20); 
            });
            nav.append(btn);
        });

        renderCharDetail(currentActiveChar, chars[currentActiveChar]);

        $('#char-nav').off('wheel').on('wheel', function(e) {
            if (e.originalEvent.deltaY !== 0) {
                e.preventDefault();
                this.scrollLeft += e.originalEvent.deltaY;
            }
        });
    }

