    function renderOptTab() {
        const rawContent = $('#raw-store').html();
        const opts = parseOptions(rawContent);

        if (opts.length === 0) {
            $('#page-opt').html('<div id="opt-list" style="display:flex;flex-direction:column;gap:6px"><div style="text-align:center;padding:20px;color:#666;font-size:12px">暂无行动</div></div>');
            return;
        }

        const optBox = $('<div id="opt-list" style="display:flex;flex-direction:column;gap:6px"></div>');
        opts.forEach(o => {
            const btn = $(`<div class="opt-btn">${o.html}</div>`);
            btn.on('click', function(e) {
                e.stopPropagation(); $('.opt-btn').removeClass('active'); $(this).addClass('active');
                try {
                    let inp = window.parent?.document?.querySelector('#send_textarea') || document.querySelector('#send_textarea');
                    if (inp) {
                        const txt = cleanInputText(o.text); const cur = inp.value.trim();
                        inp.value = cur ? `${cur}\n${txt}` : txt;
                        inp.dispatchEvent(new Event('input', { bubbles: true })); inp.focus();
                    }
                } catch (err) {}
            });
            optBox.append(btn);
        });
        $('#page-opt').empty().append(optBox);
    }

    function doRenderTab(tabId, sd) {
        try {
            if (tabId === 'page-user') renderUserTab(sd);
            else if (tabId === 'page-story') renderStoryTab(sd);
            else if (tabId === 'page-chars') renderCharsTab(sd);
            else if (tabId === 'page-opt') renderOptTab();
            tabRendered[tabId] = true;
        } catch (err) {
            $(`#${tabId}`).html('<div style="padding:20px;color:red;font-size:12px">UI Error: ' + err.message + '</div>');
        }
    }

    // 主更新函数，支持接收指定数据强制刷新
    function render(forcedData) {
        try {
            const sd = forcedData || getData();
            renderHeader(sd);

            // 标记所有Tab缓存过期
            tabRendered = { 'page-user': false, 'page-story': false, 'page-opt': false };

            // 实时刷新当前停留的页面
            const activeTabId = $('.tab-page.active').attr('id');
            if (activeTabId) {
                doRenderTab(activeTabId, sd);
            }
        } catch (e) { console.error("Main Render Error:", e); }
    }

    // 点击导航按钮的逻辑：处理异步显示加载提示
    window.switchTab = function(id, btn, theme) {
        const card = $('.tide-card');
        const isSameBtn = $(btn).hasClass('active');
        const isExpanded = card.hasClass('expanded');

        lastActiveTabBtn = $(btn);

        $('.tab-page').removeClass('active'); 
        $(`#${id}`).addClass('active');
        $('.nav-btn').removeClass('active');
        $('body').removeClass('theme-blue theme-purple theme-pink theme-green').addClass(theme);

        if (isSameBtn && isExpanded) {
            card.removeClass('expanded');
            $(btn).removeClass('active');
        } else {
            $(btn).addClass('active');
            card.addClass('expanded');
        }

        // 懒加载逻辑
        if (!tabRendered[id]) {
            $(`#${id}`).html('<div style="text-align:center;padding:40px 0;color:var(--accent-color);font-weight:bold;animation: pulse 1s infinite;">数据装载中...</div>');
            setTimeout(() => { doRenderTab(id, getData()); }, 30);
        }
    }

    async function init() {
        if (window.waitGlobalInitialized) await waitGlobalInitialized('Mvu');

        $('body').addClass('theme-blue');
        $('.tab-page').removeClass('active');
        $('#page-user').addClass('active'); // 强制开局第一面为状态页面

        // 初始首次渲染
        render();

        // 监听 MVU 变量更新：加入防抖功能并读取事件参数中的最新数据
        if (window.eventOn && window.Mvu) {
            eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (vars) => {
                if (renderDebounceTimer) clearTimeout(renderDebounceTimer);
                // 等待 100 毫秒后再渲染，将 MVU 底层传出的最新变量传给 render
                renderDebounceTimer = setTimeout(() => { 
                    render(vars && vars.stat_data ? vars.stat_data : null); 
                }, 100);
            });
        }

        lastActiveTabBtn = $('.nav-btn').first();

        $('.tide-header').off('click').on('click', function() {
            const card = $('.tide-card');
            if (card.hasClass('expanded')) {
                card.removeClass('expanded');
                $('.nav-btn').removeClass('active');
            } else {
                if(lastActiveTabBtn && lastActiveTabBtn.length) lastActiveTabBtn.click();
                else $('.nav-btn').first().click();
            }
        });
        $('.nav-btn').removeClass('active');
    }

    $(() => setTimeout(init, 100));
</script>
</head>
